            onError: options.onError,
        }),
        host,
    };
}

export function getUnixSocketPath(serverId, serverDirectory) {
    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(serverId)) {
        throw new TypeError("Unix serverId must be a canonical lowercase UUIDv4");
    }
    return join(serverDirectory, `${serverId}.sock`);
}

async start(accept) {
        if (this.server)
            throw new Error("Unix listener is already started");
        if (this.closing)
            throw new Error("Unix listener is closing or closed");
        this.accept = accept;
        const ownedBindPath = getOwnedBindPath(this.path);
        await mkdir(dirname(this.path), { recursive: true, mode: 0o700 });
        await removeStaleSocket(this.path);
        await removeStaleSocket(ownedBindPath);
        this.ownedBindPath = ownedBindPath;
        const server = createServer((socket) => this.acceptSocket(socket));
        server.on("error", (error) => this.reportError(error));
        this.server = server;
        try {
            await new Promise((resolve, reject) => {
                const onError = (error) => {
                    server.off("listening", onListening);
                    reject(error);
                };
                const onListening = () => {
                    server.off("error", onError);
                    resolve();
                };
                server.once("error", onError);
                server.once("listening", onListening);
                server.listen(ownedBindPath);
            });
            const stats = await lstat(ownedBindPath);
            if (!stats.isSocket())
                throw new Error(`Unix listener path is not a socket after binding: ${ownedBindPath}`);
            this.socketIdentity = { dev: stats.dev, ino: stats.ino };
            await link(ownedBindPath, this.path);
            await setSocketMode(this.path, this.mode);
            await removePath(ownedBindPath);
            this.ownedBindPath = undefined;
        }
        catch (error) {
            await this.closeServerAndCleanup(server);
            this.server = undefined;
            throw error;
        }
    }

async close() {
        if (this.closePromise)
            return this.closePromise;
        this.closing = true;
        this.closePromise = this.closeInternal();
        return this.closePromise;
    }

acceptSocket(socket) {
        if (this.closing) {
            socket.destroy();
            return;
        }
        const connection = new UnixByteConnection(socket, this.options.gracefulCloseTimeoutMs, this.options.maxPendingBytes);
        this.connections.add(connection);
        const accept = this.accept;
        if (!accept) {
            socket.destroy();
            return;
        }
        const handler = accept(connection);
        socket.on("data", (chunk) => {
            handler.onData(new Uint8Array(chunk.buffer, chunk.byteOffset, chunk.byteLength));
        });
        socket.on("error", (error) => {
            handler.onError(error);
            socket.destroy();
        });
        socket.once("close", () => {
            connection.markClosed();
            this.connections.delete(connection);
            handler.onClose();
        });
    }

async closeInternal() {
        const serverClosed = this.server ? this.closeServerAndCleanup(this.server) : this.cleanupOwnedSocket();
        await Promise.all([...this.connections].map((connection) => connection.close()));
        await serverClosed;
        if (this.ownedBindPath)
            await removePath(this.ownedBindPath);
        this.ownedBindPath = undefined;
        this.connections.clear();
        this.server = undefined;
    }

async closeServerAndCleanup(server) {
        try {
            await closeNetServer(server, (error) => this.reportError(error));
        }
        finally {
            // Remove an unpublished startup bind path before the public route.
            if (this.ownedBindPath)
                await removePath(this.ownedBindPath);
            this.ownedBindPath = undefined;
            await this.cleanupOwnedSocket();
        }
    }

async cleanupOwnedSocket() {
        const identity = this.socketIdentity;
        this.socketIdentity = undefined;
        if (!identity)
            return;
        let current;
        try {
            current = await lstat(this.path);
        }
        catch (error) {
            if (isErrorCode(error, "ENOENT"))
                return;
            throw error;
        }
        if (!current.isSocket() || current.dev !== identity.dev || current.ino !== identity.ino)
            return;
        const preserved = join(dirname(this.path), `cleanup-${randomUUID().slice(0, 6)}`);
        try {
            await rename(this.path, preserved);
        }
        catch (error) {
            if (isErrorCode(error, "ENOENT"))
                return;
            throw error;
        }
        const moved = await lstat(preserved);
        if (moved.isSocket() && moved.dev === identity.dev && moved.ino === identity.ino) {
            await removePath(preserved);
            return;
        }
        try {
            await lstat(this.path);
        }
        catch (error) {
            if (isErrorCode(error, "ENOENT"))
                await rename(preserved, this.path);
            else
                throw error;
        }
        throw new Error(`Unix listener path changed during cleanup; preserved replacement at ${preserved}`);
    }

reportError(error) {
        try {
            this.options.onError?.(error instanceof Error ? error : new Error(String(error)));
        }
        catch {
            // Error observers cannot affect listener state.
        }
    }

get closed() {
        return this.closedValue;
    }

send(chunk) {
        if (!(chunk instanceof Uint8Array)) {
            return Promise.reject(new TypeError("Unix connection chunks must be Uint8Array"));
        }
        if (this.closedValue || this.closing)
            return Promise.reject(new Error("Unix connection is closed"));
        if (this.pendingBytes + chunk.byteLength > this.maxPendingBytes) {
            return Promise.reject(new Error("Unix connection exceeded its pending byte limit"));
        }
        this.pendingBytes += chunk.byteLength;
        const bytes = chunk.slice();
        const write = this.writeTail.then(() => this.write(bytes));
        const tracked = write.finally(() => {
            this.pendingBytes -= bytes.byteLength;
        });
        this.writeTail = tracked.catch(() => { });
        return tracked;
    }

close(finalChunk) {
        if (this.closedValue || this.socket.destroyed) {
            this.markClosed();
            return Promise.resolve();
        }
        if (this.closePromise)
            return this.closePromise;
        this.closing = true;
        const finalBytes = finalChunk?.slice();
        this.closePromise = new Promise((resolve) => {
            this.resolveClose = resolve;
            const timer = setTimeout(() => {
                if (!this.socket.destroyed)
                    this.socket.destroy();
                this.markClosed();
            }, this.gracefulCloseTimeoutMs);
            timer.unref();
            this.socket.once("close", () => clearTimeout(timer));
            void this.writeTail.then(() => {
                if (this.socket.destroyed) {
                    this.markClosed();
                    return;
                }
                try {
                    if (finalBytes)
                        this.socket.end(finalBytes);
                    else
                        this.socket.end();
                }
                catch {
                    this.socket.destroy();
                }
            });
        });
        return this.closePromise;
    }

markClosed() {
        if (this.closedValue)
            return;
        this.closedValue = true;
        this.closing = true;
        this.resolveClose?.();
        this.resolveClose = undefined;
    }

write(chunk) {
        if (this.closedValue || this.closing || !this.socket.writable) {
            return Promise.reject(new Error("Unix connection is closed"));
        }
        return new Promise((resolve, reject) => {
            let settled = false;
            const onClose = () => finish(new Error("Unix connection closed during write"));
            const finish = (error) => {
                if (settled)
                    return;
                settled = true;
                this.socket.off("close", onClose);
                if (error)
                    reject(error);
                else
                    resolve();
            };
            this.socket.once("close", onClose);
            try {
                this.socket.write(chunk, finish);
            }
            catch (error) {
                finish(error instanceof Error ? error : new Error(String(error)));
            }
        });
    }

function getOwnedBindPath(path) {
    const suffix = createHash("sha256").update(path).digest("hex").slice(0, 8);
    return join(dirname(path), `bind-${suffix}`);
}

async function removeStaleSocket(path) {
    let original;
    try {
        original = await lstat(path);
    }
    catch (error) {
        if (isErrorCode(error, "ENOENT"))
            return;
        throw error;
    }
    if (!original.isSocket())
        throw new Error(`Refusing to remove non-socket Unix listener path: ${path}`);
    if (await isSocketLive(path))
        throw new Error(`Unix listener is already running: ${path}`);
    const preserved = join(dirname(path), `stale-${randomUUID().slice(0, 6)}`);
    try {
        await rename(path, preserved);
    }
    catch (error) {
        if (isErrorCode(error, "ENOENT"))
            return;
        throw error;
    }
    const current = await lstat(preserved);
    if (!current.isSocket() || current.dev !== original.dev || current.ino !== original.ino) {
        try {
            await lstat(path);
        }
        catch (error) {
            if (isErrorCode(error, "ENOENT"))
                await rename(preserved, path);
            else
                throw error;
        }
        throw new Error(`Unix listener path changed while checking for a stale socket: ${path}`);
    }
    await removePath(preserved);
}

async function removePath(path) {
    try {
        await unlink(path);
    }
    catch (error) {
        if (!isErrorCode(error, "ENOENT"))
            throw error;
    }
}

function isSocketLive(path) {
    return new Promise((resolve, reject) => {
        const socket = createConnection(path);
        let settled = false;
        let timer;
        const finish = (result, error) => {
            if (settled)
                return;
            settled = true;
            if (timer)
                clearTimeout(timer);
            socket.removeAllListeners();
            socket.destroy();
            if (error)
                reject(error);
            else
                resolve(result);
        };
        socket.once("connect", () => finish(true));
        socket.once("error", (error) => {
            if (["ECONNREFUSED", "ENOENT", "EPIPE", "ECONNRESET"].includes(error.code ?? "")) {
                finish(false);
                return;
            }
            finish(false, error);
        });
        timer = setTimeout(() => finish(true), SOCKET_PROBE_TIMEOUT_MS);
        timer.unref();
    });
}

async function setSocketMode(path, mode) {
    if (process.platform === "win32")
        return;
    try {
        await chmod(path, mode);
    }
    catch (error) {
        if (!isErrorCode(error, "ENOSYS") && !isErrorCode(error, "ENOTSUP"))
            throw error;
    }
}

function closeNetServer(server, reportError) {
    if (!server.listening)
        return Promise.resolve();
    return new Promise((resolve) => {
        server.close((error) => {
            if (error)
                reportError(error);
            resolve();
        });
    });
}

function isErrorCode(error, code) {
    return error instanceof Error && "code" in error && error.code === code;
}

export function createUnixListener(options) {
    return new UnixListener(options);
}

function resolveUnixListenerOptions(options) {
    if (!options.path)
        throw new TypeError("Server Unix socket path must not be empty");
    const mode = options.mode ?? DEFAULT_SOCKET_MODE;
    if (!Number.isInteger(mode) || mode < 0 || mode > 0o777) {
        throw new TypeError("Server Unix socket mode must be an integer between 0 and 0o777");
    }
    const maxFrameLength = options.maxFrameLength ?? DEFAULT_MAX_FRAME_LENGTH;
    if (!Number.isSafeInteger(maxFrameLength) || maxFrameLength <= 0 || maxFrameLength > MAX_UINT32) {
        throw new TypeError(`Server maxFrameLength must be an integer between 1 and ${MAX_UINT32}`);
    }
    const maxPendingBytes = options.maxPendingBytes ?? maxFrameLength * 4;
    if (!Number.isSafeInteger(maxPendingBytes) || maxPendingBytes < maxFrameLength + 4) {
        throw new TypeError("Server maxPendingBytes must be a safe integer at least maxFrameLength + 4");
    }
    const gracefulCloseTimeoutMs = options.gracefulCloseTimeoutMs ?? DEFAULT_GRACEFUL_CLOSE_TIMEOUT_MS;
    if (!Number.isSafeInteger(gracefulCloseTimeoutMs) ||
        gracefulCloseTimeoutMs <= 0 ||
        gracefulCloseTimeoutMs > MAX_TIMER_DELAY_MS) {
        throw new TypeError(`Server gracefulCloseTimeoutMs must be an integer between 1 and ${MAX_TIMER_DELAY_MS}`);
    }
    return {
        path: options.path,
        mode,
        maxPendingBytes,
        gracefulCloseTimeoutMs,
        onError: options.onError,
    };
}

export function createUnixServer(host, options) {
    const listener = createUnixListener({
        path: options.path,
        mode: options.mode,
        maxFrameLength: options.maxFrameLength,
        maxPendingBytes: options.maxPendingBytes,
        gracefulCloseTimeoutMs: options.gracefulCloseTimeoutMs,
        onError: options.onError,
    });
    return new Server(host, {
        listeners: [listener],
        maxFrameLength: options.maxFrameLength,
        handshakeTimeoutMs: options.handshakeTimeoutMs,
        onConnectionCountChanged: options.onConnectionCountChanged,
        serverId: options.serverId,
        onError: options.onError,
    });
}

decode() {
        const value = this.readItem(0);
        if (this.offset !== this.bytes.byteLength)
            throw new CborError("CBOR payload contains trailing data");
        return value;
    }

readItem(depth) {
        if (depth > this.options.maxDepth) {
            throw new CborError(`CBOR nesting depth exceeds configured limit of ${this.options.maxDepth}`);
        }
        const initial = this.readByte();
        const majorType = initial >>> 5;
        const additionalInformation = initial & 0x1f;
        switch (majorType) {
            case 0:
                return this.readArgument(additionalInformation);
            case 1: {
                const value = -1 - this.readArgument(additionalInformation);
                if (!Number.isSafeInteger(value))
                    throw new CborError("Decoded CBOR integer is outside the safe range");
                return value;
            }
            case 2: {
                const length = this.readLength(additionalInformation, "byte string", this.options.maxByteLength);
                return new Uint8Array(this.readBytes(length));
            }
            case 3: {
                const length = this.readLength(additionalInformation, "text string", this.options.maxByteLength);
                const bytes = this.readBytes(length);
                try {
                    return textDecoder.decode(bytes);
                }
                catch (_error) {
                    throw new CborError("CBOR text string contains invalid UTF-8");
                }
            }
            case 4: {
                const length = this.readLength(additionalInformation, "array", this.options.maxContainerLength);
                const result = [];
                for (let index = 0; index < length; index++)
                    result.push(this.readItem(depth + 1));
                return result;
            }
            case 5: {
                const length = this.readLength(additionalInformation, "map", this.options.maxContainerLength);
                const result = {};
                const keys = new Set();
                for (let index = 0; index < length; index++) {
                    const key = this.readItem(depth + 1);
                    if (typeof key !== "string")
                        throw new CborError("CBOR map keys must be strings");
                    if (keys.has(key))
                        throw new CborError("CBOR map contains a duplicate key");
                    keys.add(key);
                    Object.defineProperty(result, key, {
                        configurable: true,
                        enumerable: true,
                        value: this.readItem(depth + 1),
                        writable: true,
                    });
                }
                return result;
            }
            case 6:
                throw new CborError("CBOR tags are not supported");
            case 7:
                return this.readSimple(additionalInformation);
            default:
                throw new CborError("Malformed CBOR major type");
        }
    }

readSimple(additionalInformation) {
        switch (additionalInformation) {
            case 20:
                return false;
            case 21:
                return true;
            case 22:
                return null;
            case 27: {
                const bytes = this.readBytes(8);
                const value = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength).getFloat64(0, false);
                if (!Number.isFinite(value))
                    throw new CborError("Decoded CBOR number must be finite");
                if (Number.isInteger(value) && !Number.isSafeInteger(value)) {
                    throw new CborError("Decoded CBOR integer is outside the safe range");
                }
                return value;
            }
            case 31:
                throw new CborError("CBOR break marker is not supported");
            default:
                throw new CborError("Unsupported CBOR simple value or floating-point width");
        }
    }

readLength(additionalInformation, kind, limit) {
        if (additionalInformation === 31)
            throw new CborError(`Indefinite-length CBOR ${kind}s are not supported`);
        const length = this.readArgument(additionalInformation);
        if (length > limit)
            throw new CborError(`CBOR ${kind} length exceeds configured limit of ${limit}`);
        return length;
    }

readArgument(additionalInformation) {
        if (additionalInformation < 24)
            return additionalInformation;
        switch (additionalInformation) {
            case 24:
                return this.readByte();
            case 25: {
                const bytes = this.readBytes(2);
                return bytes[0] * 0x100 + bytes[1];
            }
            case 26: {
                const bytes = this.readBytes(4);
                return bytes[0] * 0x1_000_000 + bytes[1] * 0x1_0000 + bytes[2] * 0x100 + bytes[3];
            }
            case 27: {
                const high = this.readArgument(26);
                const low = this.readArgument(26);
                if (high > 0x1f_ffff)
                    throw new CborError("Decoded CBOR integer or length is outside the safe range");
                return high * UINT32_BASE + low;
            }
            case 31:
                throw new CborError("Indefinite-length CBOR items are not supported");
            default:
                throw new CborError("Malformed CBOR additional information");
        }
    }

readByte() {
        if (this.offset >= this.bytes.byteLength)
            throw new CborError("Truncated CBOR payload");
        const value = this.bytes[this.offset];
        this.offset++;
        return value;
    }

readBytes(length) {
        if (length > this.bytes.byteLength - this.offset)
            throw new CborError("Truncated CBOR payload");
        const value = this.bytes.subarray(this.offset, this.offset + length);
        this.offset += length;
        return value;
    }

export function decodeCbor(bytes, options) {
    if (!(bytes instanceof Uint8Array))
        throw new TypeError("CBOR input must be a Uint8Array");
    const resolved = resolveOptions(options);
    if (bytes.byteLength > resolved.maxByteLength) {
        throw new CborError(`CBOR byte length exceeds configured limit of ${resolved.maxByteLength}`);
    }
    return new CborReader(bytes, resolved).decode();
}

writeByte(value) {
        this.ensureCapacity(1);
        this.buffer[this.offset] = value;
        this.offset++;
    }

writeBytes(bytes) {
        this.ensureCapacity(bytes.byteLength);
        this.buffer.set(bytes, this.offset);
        this.offset += bytes.byteLength;
    }

writeUint16(value) {
        this.ensureCapacity(2);
        this.buffer[this.offset] = value >>> 8;
        this.buffer[this.offset + 1] = value;
        this.offset += 2;
    }

writeUint32(value) {
        this.ensureCapacity(4);
        this.buffer[this.offset] = value >>> 24;
        this.buffer[this.offset + 1] = value >>> 16;
        this.buffer[this.offset + 2] = value >>> 8;
        this.buffer[this.offset + 3] = value;
        this.offset += 4;
    }

writeUint64(value) {
        const high = Math.floor(value / UINT32_BASE);
        const low = value - high * UINT32_BASE;
        this.writeUint32(high);
        this.writeUint32(low);
    }

writeFloat64(value) {
        this.ensureCapacity(9);
        this.buffer[this.offset] = 0xfb;
        new DataView(this.buffer.buffer).setFloat64(this.offset + 1, value, false);
        this.offset += 9;
    }

finish() {
        return this.buffer.slice(0, this.offset);
    }

ensureCapacity(additionalBytes) {
        const required = this.offset + additionalBytes;
        if (required > this.maxByteLength) {
            throw new CborError(`CBOR byte length exceeds configured limit of ${this.maxByteLength}`);
        }
        if (required <= this.buffer.byteLength)
            return;
        let capacity = Math.max(1, this.buffer.byteLength);
        while (capacity < required)
            capacity = Math.min(this.maxByteLength, Math.max(required, capacity * 2));
        const expanded = new Uint8Array(capacity);
        expanded.set(this.buffer);
        this.buffer = expanded;
    }

function writeArgument(writer, majorType, value) {
    const prefix = majorType << 5;
    if (value < 24) {
        writer.writeByte(prefix | value);
    }
    else if (value <= 0xff) {
        writer.writeByte(prefix | 24);
        writer.writeByte(value);
    }
    else if (value <= 0xffff) {
        writer.writeByte(prefix | 25);
        writer.writeUint16(value);
    }
    else if (value <= MAX_UINT32) {
        writer.writeByte(prefix | 26);
        writer.writeUint32(value);
    }
    else {
        writer.writeByte(prefix | 27);
        writer.writeUint64(value);
    }
}

function isPlainObject(value) {
    if (typeof value !== "object" || value === null)
        return false;
    const prototype = Object.getPrototypeOf(value);
    return prototype === Object.prototype || prototype === null;
}

function encodeText(writer, value, options) {
    const bytes = textEncoder.encode(value);
    if (bytes.byteLength > options.maxByteLength) {
        throw new CborError(`CBOR text string length exceeds configured limit of ${options.maxByteLength}`);
    }
    if (textDecoder.decode(bytes) !== value)
        throw new CborError("CBOR text strings must contain valid Unicode scalar values");
    writeArgument(writer, 3, bytes.byteLength);
    writer.writeBytes(bytes);
}

function encodeValue(writer, value, options, depth, ancestors) {
    if (depth > options.maxDepth)
        throw new CborError(`CBOR nesting depth exceeds configured limit of ${options.maxDepth}`);
    if (value === null) {
        writer.writeByte(0xf6);
        return;
    }
    if (typeof value === "boolean") {
        writer.writeByte(value ? 0xf5 : 0xf4);
        return;
    }
    if (typeof value === "number") {
        if (!Number.isFinite(value))
            throw new CborError("CBOR numbers must be finite");
        if (Number.isInteger(value) && !Object.is(value, -0)) {
            if (!Number.isSafeInteger(value))
                throw new CborError("CBOR integers must be safe JavaScript integers");
            if (value >= 0)
                writeArgument(writer, 0, value);
            else
                writeArgument(writer, 1, -1 - value);
        }
        else {
            writer.writeFloat64(value);
        }
        return;
    }
    if (typeof value === "string") {
        encodeText(writer, value, options);
        return;
    }
    if (value instanceof Uint8Array) {
        if (value.byteLength > options.maxByteLength) {
            throw new CborError(`CBOR byte string length exceeds configured limit of ${options.maxByteLength}`);
        }
        writeArgument(writer, 2, value.byteLength);
        writer.writeBytes(value);
        return;
    }
    if (Array.isArray(value)) {
        if (ancestors.has(value))
            throw new CborError("CBOR values must not contain cycles");
        if (value.length > options.maxContainerLength) {
            throw new CborError(`CBOR array length exceeds configured limit of ${options.maxContainerLength}`);
        }
        ancestors.add(value);
        try {
            writeArgument(writer, 4, value.length);
            for (let index = 0; index < value.length; index++) {
                if (!Object.hasOwn(value, index) || value[index] === undefined) {
                    throw new CborError("CBOR arrays must not contain holes or undefined values");
                }
                encodeValue(writer, value[index], options, depth + 1, ancestors);
            }
        }
        finally {
            ancestors.delete(value);
        }
        return;
    }
    if (isPlainObject(value)) {
        if (ancestors.has(value))
            throw new CborError("CBOR values must not contain cycles");
        for (const symbol of Object.getOwnPropertySymbols(value)) {
            if (Object.prototype.propertyIsEnumerable.call(value, symbol)) {
                throw new CborError("CBOR map keys must be strings");
            }
        }
        const entries = [];
        for (const key of Object.keys(value)) {
            const entryValue = value[key];
            if (entryValue !== undefined)
                entries.push([key, entryValue]);
        }
        if (entries.length > options.maxContainerLength) {
            throw new CborError(`CBOR map length exceeds configured limit of ${options.maxContainerLength}`);
        }
        ancestors.add(value);
        try {
            writeArgument(writer, 5, entries.length);
            for (const [key, entryValue] of entries) {
                encodeText(writer, key, options);
                encodeValue(writer, entryValue, options, depth + 1, ancestors);
            }
        }
        finally {
            ancestors.delete(value);
        }
        return;
    }
    throw new CborError(`Unsupported CBOR value type: ${typeof value}`);
}

export function encodeCbor(value, options) {
    const resolved = resolveOptions(options);
    const writer = new CborWriter(resolved.maxByteLength);
    encodeValue(writer, value, resolved, 0, new Set());
    return writer.finish();
}

function resolveLimit(name, value, maximum) {
    if (!Number.isSafeInteger(value) || value < 0 || value > maximum) {
        throw new RangeError(`${name} must be an integer between 0 and ${maximum}`);
    }
    return value;
}

export function resolveOptions(options) {
    return {
        maxByteLength: resolveLimit("maxByteLength", options?.maxByteLength ?? DEFAULT_MAX_CBOR_BYTE_LENGTH, MAX_UINT32),
        maxContainerLength: resolveLimit("maxContainerLength", options?.maxContainerLength ?? DEFAULT_MAX_CBOR_CONTAINER_LENGTH, MAX_UINT32),
        maxDepth: resolveLimit("maxDepth", options?.maxDepth ?? DEFAULT_MAX_CBOR_DEPTH, MAX_CONFIGURED_DEPTH),
    };
}

export function parseClientMessage(value) {
    if (!Check(ClientMessageSchema, value) || !isJsonValue(value)) {
        throw new ProtocolValidationError("Invalid client protocol message");
    }
    return value;
}

export function parseServerMessage(value) {
    if (!Check(ServerMessageSchema, value) || !isJsonValue(value)) {
        throw new ProtocolValidationError("Invalid server protocol message");
    }
    return value;
}

function boundedErrorMessage(error) {
    if (!(error instanceof Error))
        return "Unknown codec error";
    return error.message.length <= 500 ? error.message : `${error.message.slice(0, 497)}...`;
}

function encodeProtocolMessage(value, parse, kind, options) {
    const validated = parse(value);
    try {
        const maxFrameLength = options?.maxFrameLength ?? DEFAULT_MAX_FRAME_LENGTH;
        return encodeFrame(encodeCbor(validated, { maxByteLength: maxFrameLength }));
    }
    catch (error) {
        if (error instanceof ProtocolValidationError)
            throw error;
        throw new ProtocolValidationError(`Unable to encode ${kind} protocol message: ${boundedErrorMessage(error)}`);
    }
}

export function encodeClientMessage(message, options) {
    return encodeProtocolMessage(message, parseClientMessage, "client", options);
}

export function encodeServerMessage(message, options) {
    return encodeProtocolMessage(message, parseServerMessage, "server", options);
}

