async closeServerState() {
        const connections = [...this.connections];
        for (const connection of connections) {
            connection.stage = "closing";
            clearTimeout(connection.handshakeTimeout);
        }
        await Promise.all(connections.map((connection) => this.closeConnection(connection.connection)));
        for (const connection of connections)
            this.disconnect(connection);
        const cleanup = await Promise.allSettled([this.sessions.close(BACKGROUND_CONTEXT)]);
        this.connections.clear();
        const errors = cleanup.flatMap((result) => (result.status === "rejected" ? [result.reason] : []));
        if (errors.length === 1)
            throw errors[0];
        if (errors.length > 1)
            throw new AggregateError(errors, "Failed to close server Sessions");
    }

releaseAttachment(attachment, context, publish = true) {
        attachment.releasing ??= (async () => {
            const errors = [];
            try {
                await Promise.allSettled(attachment.operations);
                try {
                    const lease = attachment.lease ?? (await attachment.acquiring);
                    if (lease)
                        await lease.release(context);
                }
                catch (error) {
                    errors.push(error);
                }
                if (errors.length === 1)
                    throw errors[0];
                if (errors.length > 1)
                    throw new AggregateError(errors, "Failed to release Session attachment");
            }
            finally {
                await this.clearAttachment(attachment, context, publish);
            }
        })();
        return attachment.releasing;
    }

